// TodoPeerInvokeParams holds the values a parent's `<param>` and
// `namelist` give this machine's variables before it starts (§scxml-6.4.1). A
// variable left nil keeps the value its `<data>` gave it.
type TodoPeerInvokeParams struct {
	VNode *uint64
	VHub *bool
	VMine *uint32
	VMixed *int64
	VKnown *bool
	VWasLive *bool
	VIsLive *bool
	VPresent *bool
	VRefusals *uint32
}

// AcceptParams gives this machine the values params carries, in place of the
// ones its `<data>` gave. Called before it initializes (§scxml-6.4.1).
func (p *TodoPeerPolicy) AcceptParams(params TodoPeerInvokeParams) {
	if params.VNode != nil {
		p.vNode = *params.VNode
	}
	if params.VHub != nil {
		p.vHub = *params.VHub
	}
	if params.VMine != nil {
		p.vMine = *params.VMine
	}
	if params.VMixed != nil {
		p.vMixed = *params.VMixed
	}
	if params.VKnown != nil {
		p.vKnown = *params.VKnown
	}
	if params.VWasLive != nil {
		p.vWasLive = *params.VWasLive
	}
	if params.VIsLive != nil {
		p.vIsLive = *params.VIsLive
	}
	if params.VPresent != nil {
		p.vPresent = *params.VPresent
	}
	if params.VRefusals != nil {
		p.vRefusals = *params.VRefusals
	}
}



// No script engine needed for this state machine.
func (p *TodoPeerPolicy) InitializeDataModel(eng *sce.Engine[TodoPeerState, TodoPeerEvent]) {}

// SetParamValueInScriptEngine is a no-op for state machines without script engine.
func (p *TodoPeerPolicy) SetParamValueInScriptEngine(name string, value interface{}) {}


// ExecutePendingInvokes is a no-op (no invokes in this SM).
func (p *TodoPeerPolicy) ExecutePendingInvokes(engine *sce.Engine[TodoPeerState, TodoPeerEvent]) {}

// TickChildren is a no-op (no invokes in this SM).
func (p *TodoPeerPolicy) TickChildren(engine *sce.Engine[TodoPeerState, TodoPeerEvent]) {}

// DeliverToParent delivers a delayed `<send target="#_parent">` whose wait is
// over, with the payload an immediate one carries (W3C SCXML 6.2 + 6.4). It
// waited in this machine's own queue, so `<cancel>` reached it and a child that
// ended first dropped it — the engine dispatches nothing once final. Emitted for
// every machine, since the one that needs it is an invoked child, which need not
// invoke anything itself.
func (p *TodoPeerPolicy) DeliverToParent(eventName, eventData string) bool {
	if p.ParentExternalQueue == nil {
		return false
	}
	p.ParentExternalQueue.Push(sce.ParentEvent{Name: eventName, Data: eventData})
	return true
}

// HasParentSession answers whether a session invoked this one (W3C SCXML C.1):
// the queue the invoking parent installs is the link to it.
func (p *TodoPeerPolicy) HasParentSession() bool {
	return p.ParentExternalQueue != nil
}

